<script lang="ts">
	import { axes } from '../haiku/axes';
	import { noise } from '../haiku/noise';
	import { mulberry32, randomSeed } from '../haiku/rng';

	const word = 'peni.sh';
	// Same axes and generator as the haiku, fresh per load, so the two grow alike.
	const values = noise(word.length, mulberry32(randomSeed()));
	const chars = [...word].map((ch, i) => {
		const [grow, thck] = axes(values[i]);
		return { ch, style: `font-variation-settings: 'grow' ${grow}, 'THCK' ${thck}` };
	});
</script>

